import {writeMol,parseMol} from './chem-core.mjs';
export class StructureEditor{
 constructor(container,{graph,saved,onSave,onStatus}){this.container=container;this.onSave=onSave;this.onStatus=onStatus;this.version=0;this.closed=false;this.setting=true;this.ready=false;this.frame=document.createElement('iframe');this.frame.className='structure-editor';this.frame.title='Ketcher standalone structure editor';this.frame.setAttribute('loading','eager');this.frame.src='./editor/index.html?disableMacromoleculesEditor=true&hiddenControls=recognize,miew,about,help,arrows,reaction-mapping-tools,reaction-plus,analyse,check';this.listener=e=>{if(e.origin===location.origin&&e.source===this.frame.contentWindow&&e.data?.eventType==='init')this.initialize(graph,saved)};window.addEventListener('message',this.listener);container.append(this.frame);this.frame.addEventListener('load',()=>this.initialize(graph,saved));this.poll=setInterval(()=>this.initialize(graph,saved),300);this.timeout=setTimeout(()=>{if(!this.ready&&!this.closed)this.onStatus?.('The editor is taking longer to load. Its first download includes the local chemistry engine. Use Reload editor if the connection failed.','warning')},35000)}
 async initialize(graph,saved){if(this.closed||this.initializing||this.ready)return;let k;try{k=this.frame.contentWindow?.ketcher}catch{return}if(!k?.getMolfile)return;this.initializing=true;clearInterval(this.poll);try{this.api=k;await k.setMolecule(saved?.ket||saved?.mol||writeMol(graph));if(this.closed)return;this.ready=true;this.setting=false;clearTimeout(this.timeout);this.subscription=k.editor.subscribe('change',()=>{if(this.setting||this.closed)return;clearTimeout(this.debounce);this.debounce=setTimeout(()=>this.capture(true),500)});this.onStatus?.('Drawing ready · changes save automatically','ready');await this.capture(false)}catch(e){this.onStatus?.('Could not load the copied structure: '+e.message,'warning')}finally{this.initializing=false}}
 async capture(dirty=false){if(!this.ready||this.closed)return null;const version=++this.version;try{const [mol,ket]=await Promise.all([this.api.getMolfile('v2000'),this.api.getKet()]);if(this.closed||version!==this.version)return null;const snapshot={mol,ket,savedAt:Date.now()};this.snapshot=snapshot;this.onSave?.(snapshot,dirty);return snapshot}catch(e){this.onStatus?.('Could not save this structure: '+e.message,'warning');return null}}
 async load(graphOrMol){if(!this.ready)return;this.setting=true;try{await this.api.setMolecule(typeof graphOrMol==='string'?graphOrMol:writeMol(graphOrMol));this.setting=false;await this.capture(true)}catch(e){this.setting=false;this.onStatus?.(e.message,'warning')}}
 async action(name){if(!this.ready)return;try{if(name==='tidy')await this.api.layout();else if(name==='undo')this.api.editor.undo();else if(name==='redo')this.api.editor.redo();await this.capture(true)}catch(e){this.onStatus?.('Editor action failed: '+e.message,'warning')}}
 async fragment(text){if(!this.ready)return;try{if(typeof this.api.addFragment!=='function')throw Error('Use the built-in Ketcher template tool instead.');await this.api.addFragment(text);this.onStatus?.('Click in the editor to place the fragment, then connect it as needed.','ready')}catch(e){this.onStatus?.(e.message,'warning')}}
 async drawing(){const shot=await this.capture(false);if(!shot)throw Error('Wait for the structure editor to finish loading.');return parseMol(shot.mol)}
 dispose(){this.closed=true;clearInterval(this.poll);clearTimeout(this.timeout);clearTimeout(this.debounce);window.removeEventListener('message',this.listener);if(this.subscription!==undefined&&this.api?.editor)this.api.editor.unsubscribe('change',this.subscription);this.frame.remove()}
}
